1	/**
2	 * Color is a set of constants which you can use to set the color of dots.
3	 *
4	 * Use it from both TypeScript and JavaScript with:
5	 *
6	 * ```javascript
7	 * game.setDot(x, y, Color.Red)
8	 * ```
9	 */
10	enum Color {
11	  Gray = "GRAY",
12	  Black = "BLACK",
13	  Red = "RED",
14	  Orange = "ORANGE",
15	  Yellow = "YELLOW",
16	  Green = "GREEN",
17	  Blue = "BLUE",
18	  Indigo = "INDIGO",
19	  Violet = "VIOLET",
20	}
21	
22	enum Direction {
23	  Left = "LEFT",
24	  Right = "RIGHT",
25	  Up = "UP",
26	  Down = "DOWN",
27	}
28	
29	/**
30	 * GameConfig is the object you pass when contructing a new {@link Game}.
31	 */
32	interface GameConfig {
33	  /**
34	   * `create(game)` is a function which is called once, just before the game
35	   * starts running. You can use it to initialise game state, if needed.
36	   */
37	  create?: (game: Game) => void;
38	  /**
39	   * `update(game)` is repeatedly called as the game runs. You can use it to
40	   * define the main functionality of your game.
41	   */
42	  update?: (game: Game) => void;
43	  /**
44	   * `onKeyPress(direction)` is a function which is called when the player
45	   * presses one of the arrow keys.
46	   */
47	  onKeyPress?: (direction: Direction) => void;
48	  /**
49	   * `onDotClicked(x, y)` is a function which is called when the player clicks
50	   * on a dot.
51	   */
52	  onDotClicked?: (x: number, y: number) => void;
53	  /**
54	   * The ID of a container to create the canvas in.
55	   */
56	  containerId?: string;
57	
58	  /**
59	   * Sets the game's frame rate. By default, this is set to 24.
60	   */
61	  frameRate?: number;
62	
63	  /**
64	   * Set the default color of the dots. By default, this is set to
65	   * {@link Color.Gray}.
66	   */
67	  defaultDotColor?: Color;
68	
69	  /**
70	   *
71	   * Sets the width of the grid. By default, this is set to 24.
72	   */
73	  gridWidth?: number;
74	
75	  /**
76	   *
77	   * Sets the height of the grid. By default, this is set to 24.
78	   */
79	  gridHeight?: number;
80	
81	  /**
82	   * @ignore
83	   */
84	  _gridWidth?: number;
85	  /**
86	   * @ignore
87	   */
88	  _gridHeight?: number;
89	
90	  /**
91	   * Specifies whether 24a2 should clear the grid at the beginning of each
92	   * frame. 24a2 clears the grid by setting the colour of every dot to
93	   * {@link GameConfig.defaultDotColor}. Setting clearGrid to false lets you
94	   * simplify the code for some games by letting 24a2 store the state for each
95	   * dot. You can use {@link Game.getDot} to read back the colour of dots. By
96	   * default, this is set to true.
97	   */
98	  clearGrid?: boolean;
99	}
100	
101	/**
102	 * Game is the object that controls the actual running of the game. You
103	 * create a new one by passing in a {@link GameConfig}. Calling `game.run()`
104	 * will start the game.
105	 *
106	 * ```javascript
107	 * let config = {
108	 *    create: create, // A function you've defined
109	 *    update: update, // A function you've defined
110	 * }
111	 *
112	 * let game = new Game(config)
113	 * game.run()
114	 * ```
115	 */
116	class Game {
117	  private _config: GameConfig;
118	
119	  private _text = "";
120	  private _ended = false;
121	  private _frameCount = 0;
122	
123	  private _dots: Array<Array<Color>>;
124	
125	  private _gridHeight = 24;
126	  private _gridWidth = 24;
127	
128	  private _clear = true;
129	
130	  private _renderer?: IOManager;
131	
132	  private _interval?: number;
133	
134	  constructor(config: GameConfig) {
135	    this._config = config;
136	
137	    // Retain support for the deprecated _gridHeight and _gridWidth config
138	    // options
139	    if (config._gridHeight && config._gridHeight > 0) {
140	      console.warn(
141	        "The config option _gridHeight is deprecated, please use gridHeight instead"
142	      );
143	      this._gridHeight = config._gridHeight;
144	    }
145	    if (config._gridWidth && config._gridWidth > 0) {
146	      console.warn(
147	        "The config option _gridWidth is deprecated, please use gridWidth instead"
148	      );
149	      this._gridWidth = config._gridWidth;
150	    }
151	
152	    if (config.gridHeight && config.gridHeight > 0) {
153	      this._gridHeight = config.gridHeight;
154	    }
155	    if (config.gridWidth && config.gridWidth > 0) {
156	      this._gridWidth = config.gridWidth;
157	    }
158	
159	    if (config.clearGrid === false) {
160	      this._clear = false;
161	    }
162	
163	    this._dots = new Array(this._gridHeight);
164	    for (let y = 0; y < this._dots.length; y++) {
165	      let row = new Array(this._gridWidth);
166	      for (let i = 0; i < row.length; i++) {
167	        row[i] = this._config.defaultDotColor || Color.Gray;
168	      }
169	      this._dots[y] = row;
170	    }
171	  }
172	
173	  /**
174	   * 24a2 games have a line of text below the grid which can be set to show
175	   * information to the player. This is commonly used to show instructions or
176	   * the player's score. Use this function to set that text.
177	   */
178	  setText(text: string): void {
179	    this._text = text;
180	  }
181	
182	  /**
183	   * Returns the number of frames that have passed since the game started. The
184	   * speed at which this increases is dependent on the frame rate. The higher
185	   * the frame rate is, the faster this number will increment, and vice versa.
186	   * You can set the frame rate with {@link GameConfig.frameRate}.
187	   *
188	   * You can use this function to do things like increase difficulty as time
189	   * goes on.
190	   */
191	  getFrameCount(): number {
192	    return this._frameCount;
193	  }
194	
195	  /**
196	   * Calling `end` stops the game loop. You should call it when the game is
197	   * finished. After you call it, the game is rendered one final time. Because
198	   * of this, you often want to `return` just after you call `game.end()` to
199	   * make sure any code after it is executed.
200	   */
201	  end(): void {
202	    this._ended = true;
203	  }
204	
205	  /**
206	   * Returns the color of a dot.
207	   */
208	  getDot(x: number, y: number): Color {
209	    if (y < 0 || y >= this._dots.length) {
210	      throw new Error(
211	        `Error trying to get dot (${x}, ${y}): y is out of bounds`
212	      );
213	    }
214	    if (x < 0 || x >= this._dots[y].length) {
215	      throw new Error(
216	        `Error trying to get dot (${x}, ${y}): x is out of bounds`
217	      );
218	    }
219	
220	    return this._dots[y][x];
221	  }
222	
223	  /**
224	   * Sets the color of a dot.
225	   */
226	  setDot(x: number, y: number, val: Color) {
227	    if (y < 0 || y >= this._dots.length) {
228	      throw new Error(
229	        `Error trying to set dot (${x}, ${y}): y is out of bounds`
230	      );
231	    }
232	    if (x < 0 || x >= this._dots[y].length) {
233	      throw new Error(
234	        `Error trying to set dot (${x}, ${y}): x is out of bounds`
235	      );
236	    }
237	
238	    this._dots[y][x] = val;
239	  }
240	
241	  /**
242	   * Calling `run` starts the game.
243	   */
244	  run() {
245	    if (!this._renderer) {
246	      // We interact with the DOM when creating the canvas, so let's wait till
247	      // the document has fully loaded
248	      if (document.readyState !== "complete") {
249	        window.addEventListener("load", this.run.bind(this));
250	        return;
251	      }
252	      this._renderer = new CanvasIOManager(
253	        this._gridHeight,
254	        this._gridWidth,
255	        this._config.containerId
256	      );
257	      if (this._config.onDotClicked) {
258	        this._renderer.registerDotClicked(this._config.onDotClicked);
259	      }
260	      if (this._config.onKeyPress) {
261	        this._renderer.registerKeyPressed(this._config.onKeyPress);
262	      }
263	    }
264	
265	    if (this._config.create) {
266	      this._config.create(this);
267	      this._render();
268	    }
269	
270	    // Initialise a `setInterval` to call a render func every X milliseconds
271	    // Delay is in milliseconds
272	    const delay = 1000 / (this._config.frameRate || 24);
273	    this._interval = window.setInterval(this._update.bind(this), delay);
274	  }
275	
276	  /**
277	   * The internal function that's called on every frame.
278	   */
279	  private _update() {
280	    if (this._ended) {
281	      window.clearInterval(this._interval);
282	      return;
283	    }
284	    this._frameCount++;
285	    if (this._clear) {
286	      this._clearGrid();
287	    }
288	    if (this._config.update) {
289	      this._config.update(this);
290	    }
291	    this._render();
292	  }
293	
294	  private _clearGrid() {
295	    this._dots.forEach((row, y) => {
296	      for (let x = 0; x < row.length; x++) {
297	        this.setDot(x, y, this._config.defaultDotColor || Color.Gray);
298	      }
299	    });
300	  }
301	
302	  private _render() {
303	    if (!this._renderer) {
304	      console.error("renderer undefined");
305	      return;
306	    }
307	    for (let y = 0; y < this._dots.length; y++) {
308	      const row = this._dots[y];
309	      for (let x = 0; x < row.length; x++) {
310	        const colour = row[x];
311	        this._renderer.setDot(x, y, colour);
312	      }
313	    }
314	    this._renderer.setText(this._text);
315	  }
316	}
317	
318	/**
319	 * @ignore
320	 * IOManager is the interface used by {@link Game} to manage the game's input
321	 * (e.g. keyboard or mouse events) and output (drawing the game).
322	 * IOManager does not form part of 24a2's public API, and can change without
323	 * warning
324	 */
325	interface IOManager {
326	  // Sets the colour of a dot
327	  setDot: (x: number, y: number, val: Color) => void;
328	  // Sets the text written
329	  setText: (text: string) => void;
330	  // Registers a function that the IOManager should call when a dot is clicked
331	  registerDotClicked: (dotClicked: (x: number, y: number) => void) => void;
332	  // Registers a function that should be called when a direction key is pressed
333	  registerKeyPressed: (keyPressed: (direction: Direction) => void) => void;
334	}
335	
336	/**
337	 * @ignore
338	 * CanvasIOManager is the object that manages 24a2's input (capturing keyboard
339	 * and mouse events) and output (rendering the game to a HTML Canvas). It's the
340	 * only bit of 24a2 which is aware we're running in a browser.
341	 * CanvasIOManager does not form part of 24a2's public API, and can change
342	 * without warning
343	 */
344	class CanvasIOManager {
345	  private _gridHeight: number;
346	  private _gridWidth: number;
347	
348	  // Variables used when rendering the grid
349	  private _dotSize = 16;
350	  private _gapSize = 8;
351	
352	  private _canvas: HTMLCanvasElement;
353	  private _ctx: CanvasRenderingContext2D;
354	
355	  private _dotClicked?: (x: number, y: number) => void;
356	  private _keyPressed?: (direction: Direction) => void;
357	
358	  constructor(gridHeight: number, gridWidth: number, containerId?: string) {
359	    this._gridHeight = gridHeight;
360	    this._gridWidth = gridWidth;
361	
362	    const { canvas, ctx } = this._createCanvasContext(containerId);
363	    this._ctx = ctx;
364	    this._canvas = canvas;
365	
366	    this._listenForMouseClick();
367	    this._listenForKeyPress();
368	  }
369	
370	  registerDotClicked(dotClicked: (x: number, y: number) => void): void {
371	    this._dotClicked = dotClicked;
372	  }
373	
374	  registerKeyPressed(keyPressed: (direction: Direction) => void): void {
375	    this._keyPressed = keyPressed;
376	  }
377	
378	  private _listenForMouseClick() {
379	    function onMouseClick(this: CanvasIOManager, event: MouseEvent) {
380	      if (!this._dotClicked) {
381	        return;
382	      }
383	      const rect = this._canvas.getBoundingClientRect();
384	
385	      // cx and cy are the x y coordinates of the mouse click relative to the
386	      // canvas
387	      const cx = event.clientX - rect.left;
388	      const cy = event.clientY - rect.top;
389	
390	      const offset = this._dotSize + this._gapSize;
391	      // Iterate over all dot locations, and check whether the distance
392	      // between the click and the dot centre is less than the dot's
393	      // radius
394	      for (let y = 0; y < this._gridHeight; y++) {
395	        for (let x = 0; x < this._gridWidth; x++) {
396	          const dx = this._dotSize / 2 + x * offset;
397	          const dy = this._dotSize / 2 + y * offset;
398	
399	          const distance = Math.sqrt(
400	            Math.pow(cx - dx, 2) + Math.pow(cy - dy, 2)
401	          );
402	
403	          if (distance < this._dotSize / 2) {
404	            this._dotClicked(x, y);
405	            // We've found the dot, so exit early
406	            return;
407	          }
408	        }
409	      }
410	    }
411	
412	    this._canvas.addEventListener("click", onMouseClick.bind(this));
413	  }
414	
415	  private _listenForKeyPress() {
416	    function onKeyPress(this: CanvasIOManager, event: KeyboardEvent) {
417	      if (!this._keyPressed) {
418	        return;
419	      }
420	
421	      // TODO: We currently ignore repeat keydown events. These are fired when
422	      // a key is held down. We do this because there's a pause between the
423	      // first (repeat: false) event and subsequent (repeat: true) events. This
424	      // causes jittery behaviour.
425	      // We should probably do something like call this._keyPressed at a
426	      // constant rate.
427	      // In the meantime, we just ignore repeated events. This is also how the
428	      // P5 implementation worked.
429	      if (event.repeat) {
430	        return;
431	      }
432	
433	      switch (event.key) {
434	        case "ArrowUp":
435	          event.preventDefault();
436	          this._keyPressed(Direction.Up);
437	          return;
438	        case "ArrowDown":
439	          event.preventDefault();
440	          this._keyPressed(Direction.Down);
441	          return;
442	        case "ArrowLeft":
443	          event.preventDefault();
444	          this._keyPressed(Direction.Left);
445	          return;
446	        case "ArrowRight":
447	          event.preventDefault();
448	          this._keyPressed(Direction.Right);
449	          return;
450	      }
451	    }
452	
453	    document.addEventListener("keydown", onKeyPress.bind(this));
454	  }
455	
456	  private _createCanvasContext(
457	    containerId?: string
458	  ): { canvas: HTMLCanvasElement; ctx: CanvasRenderingContext2D } {
459	    const pixelRatio = window.devicePixelRatio || 1;
460	
461	    const width =
462	      this._dotSize * this._gridWidth + this._gapSize * (this._gridWidth - 1);
463	    const height =
464	      this._dotSize * this._gridHeight +
465	      this._gapSize * (this._gridHeight - 1) +
466	      50;
467	
468	    const canvas = document.createElement("canvas");
469	    // Set the DOM/CSS sizes to get good looking drawings on high DPI screens
470	    // https://stackoverflow.com/a/26047748
471	    // https://www.html5rocks.com/en/tutorials/canvas/hidpi/
472	    canvas.style.width = width + "px";
473	    canvas.style.height = height + "px";
474	    canvas.width = width * pixelRatio;
475	    canvas.height = height * pixelRatio;
476	
477	    const parent = this._getCanvasParent(containerId);
478	    parent.appendChild(canvas);
479	
480	    const ctx = canvas.getContext("2d");
481	    if (ctx == null) {
482	      throw new Error("CanvasIOManager: error getting canvas context");
483	    }
484	    ctx.scale(pixelRatio, pixelRatio);
485	
486	    return { canvas, ctx };
487	  }
488	
489	  /**
490	   * Returns the element that should be our canvas's parent.
491	   * - If a containerId is specified, it'll be the element with that ID
492	   * - If one isn't, the parent will be the <main> element
493	   * - If a <main> element doesn't exist, we'll append one to the <body>
494	   * - If multiple <main> elements exist, the first will be the parent
495	   */
496	  private _getCanvasParent(containerId?: string): HTMLElement {
497	    if (containerId) {
498	      const parent = document.getElementById(containerId);
499	      if (!parent) {
500	        throw new Error(
501	          `CanvasIOManager: could not find element with ID ${containerId}`
502	        );
503	      }
504	      return parent;
505	    }
506	
507	    const mains = document.getElementsByTagName("main");
508	    if (mains.length > 0) {
509	      return mains[0];
510	    }
511	
512	    // No main element exists - let's create one
513	    const main = document.createElement("main");
514	    document.body.appendChild(main);
515	
516	    return main;
517	  }
518	
519	  setDot(x: number, y: number, val: Color) {
520	    // TODO: we can improve efficiency by keeping a cache of what the dot
521	    // previously was, and only writing it to the canvas if it's changed.
522	    // I'd like to have a benchmark test set up before coding this so we can
523	    // demonstrate the benefit
524	    const ctx = this._ctx;
525	    const offset = this._dotSize + this._gapSize;
526	
527	    ctx.save();
528	    // Move coordinates, so plotting a dot a (0, 0) is fully visible
529	    ctx.translate(this._dotSize / 2, this._dotSize / 2);
530	
531	    // Move coordinates again, to where the dot should be plotted
532	    ctx.translate(x * offset, y * offset);
533	
534	    // Clear the space the dot occupies. This prevents minor outline issues
535	    // when changing the colour of a dot
536	    ctx.clearRect(
537	      -this._dotSize / 2,
538	      -this._dotSize / 2,
539	      this._dotSize,
540	      this._dotSize
541	    );
542	
543	    ctx.fillStyle = this._getCSSColor(val);
544	    ctx.beginPath();
545	    ctx.arc(0, 0, this._dotSize / 2, 0, 2 * Math.PI);
546	    ctx.fill();
547	
548	    ctx.restore();
549	  }
550	
551	  private _getCSSColor(color: Color): string {
552	    switch (color) {
553	      case Color.Gray:
554	        return "gainsboro";
555	      case Color.Black:
556	        return "black";
557	      case Color.Red:
558	        return "red";
559	      case Color.Orange:
560	        return "orange";
561	      case Color.Yellow:
562	        return "gold";
563	      case Color.Green:
564	        return "green";
565	      case Color.Blue:
566	        return "blue";
567	      case Color.Indigo:
568	        return "indigo";
569	      case Color.Violet:
570	        return "violet";
571	      default:
572	        console.error(`no CSS color defined for ${color}`);
573	        return "";
574	    }
575	  }
576	
577	  setText(text: string) {
578	    const ctx = this._ctx;
579	    const textSize = 20; // px
580	    ctx.save();
581	    const textX = 0;
582	    const textY =
583	      this._dotSize * this._gridHeight +
584	      this._gapSize * (this._gridHeight - 1) +
585	      32;
586	
587	    ctx.clearRect(
588	      textX,
589	      textY - textSize,
590	      this._dotSize * this._gridWidth + this._gapSize * (this._gridWidth - 1),
591	      100 // This is a bit arbitrary - we just want to clear the whole bottom of the canvas
592	    );
593	
594	    ctx.font = `${textSize}px monospace`;
595	    ctx.fillText(text, textX, textY);
596	    ctx.restore();
597	  }
598	}
